#include <bits/stdc++.h>
using namespace std;
int main(int argc,char**argv){ if(argc!=2)return 2; ifstream f(argv[1]); long long h; unsigned long long p; int cut,rows=0; set<long long> seen; while(f>>h>>p>>cut){if(p >= (1ULL<<55)||cut<0||cut>=2048||!seen.insert(h).second){cerr<<"bad encoding or duplicate "<<h<<endl;return 1;} int out[12]={}; int bit=0; for(int i=0;i<11;i++)for(int j=i+1;j<11;j++){if((p>>bit++)&1)out[i]|=1<<j;else out[j]|=1<<i;}for(int i=0;i<11;i++){if(cut>>i&1)out[i]|=1<<11;else out[11]|=1<<i;} // independently forward paths and explicit reachability from each start
 for(int s=0;s<12;s++){int r=1<<s, old;do{old=r;for(int i=0;i<12;i++)if(r>>i&1)r|=out[i];}while(r!=old);if(r!=4095){cerr<<"not strong "<<h<<endl;return 1;}}
 long long dp[4096][12]={}; for(int i=0;i<12;i++)dp[1<<i][i]=1;for(int mask=1;mask<4096;mask++)for(int i=0;i<12;i++)if(dp[mask][i]){int next=out[i]&~mask&4095;while(next){int b=next&-next;next-=b;dp[mask|b][__builtin_ctz((unsigned)b)]+=dp[mask][i];}}long long count=accumulate(dp[4095],dp[4095]+12,0LL);if(count!=h){cerr<<"wrong count "<<h<<" got "<<count<<endl;return 1;}rows++;} if(!f.eof()){cerr<<"bad input"<<endl;return 1;}cout<<"PASS "<<rows<<" unique witnesses independently counted and strongly connected\n";}
